   106	ObjectStream::ObjectStream(XRef *xref, int objStrNumA, int recursion) {
   107	  Stream *str;
   108	  Parser *parser;
   109	  Goffset *offsets;
   110	  Object objStr, obj1;
   111	  Goffset first;
   112	  int i;
   113	
   114	  objStrNum = objStrNumA;
   115	  nObjects = 0;
   116	  objs = nullptr;
   117	  objNums = nullptr;
   118	  ok = false;
   119	
   120	  objStr = xref->fetch(objStrNum, 0, recursion);
   121	  if (!objStr.isStream()) {
   122	    return;
   123	  }
   124	
   125	  obj1 = objStr.streamGetDict()->lookup("N", recursion);
   126	  if (!obj1.isInt()) {
   127	    return;
   128	  }
   129	  nObjects = obj1.getInt();
   130	  if (nObjects <= 0) {
   131	    return;
   132	  }
   133	
   134	  obj1 = objStr.streamGetDict()->lookup("First", recursion);
   135	  if (!obj1.isInt() && !obj1.isInt64()) {
   136	    return;
   137	  }
   138	  if (obj1.isInt())
   139	    first = obj1.getInt();
   140	  else
   141	    first = obj1.getInt64();
   142	  if (first < 0) {
   143	    return;
   144	  }
   145	
   146	  // this is an arbitrary limit to avoid integer overflow problems
   147	  // in the 'new Object[nObjects]' call (Acrobat apparently limits
   148	  // object streams to 100-200 objects)
   149	  if (nObjects > 1000000) {
   150	    error(errSyntaxError, -1, "Too many objects in an object stream");
   151	    return;
   152	  }
   153	  objs = new Object[nObjects];
   154	  objNums = (int *)gmallocn(nObjects, sizeof(int));
   155	  offsets = (Goffset *)gmallocn(nObjects, sizeof(Goffset));
   156	
   157	  // parse the header: object numbers and offsets
   158	  objStr.streamReset();
   159	  str = new EmbedStream(objStr.getStream(), Object(objNull), true, first);
   160	  parser = new Parser(xref, new Lexer(xref, str), false);
   161	  for (i = 0; i < nObjects; ++i) {
   162	    obj1 = parser->getObj();
   163	    Object obj2 = parser->getObj();
   164	    if (!obj1.isInt() || !(obj2.isInt() || obj2.isInt64())) {
   165	      delete parser;
   166	      gfree(offsets);
   167	      return;
   168	    }
   169	    objNums[i] = obj1.getInt();
   170	    if (obj2.isInt())
   171	      offsets[i] = obj2.getInt();
   172	    else
   173	      offsets[i] = obj2.getInt64();
   174	    if (objNums[i] < 0 || offsets[i] < 0 ||
   175	        (i > 0 && offsets[i] < offsets[i-1])) {
   176	      delete parser;
   177	      gfree(offsets);
   178	      return;
   179	    }
   180	  }
   181	  while (str->getChar() != EOF) ;
   182	  delete parser;
   183	
   184	  // skip to the first object - this shouldn't be necessary because
   185	  // the First key is supposed to be equal to offsets[0], but just in
   186	  // case...
   187	  for (Goffset pos = first; pos < offsets[0]; ++pos) {
   188	    objStr.getStream()->getChar();
   189	  }
   190	
   191	  // parse the objects
   192	  for (i = 0; i < nObjects; ++i) {
   193	    if (i == nObjects - 1) {
   194	      str = new EmbedStream(objStr.getStream(), Object(objNull), false, 0);
   195	    } else {
   196	      str = new EmbedStream(objStr.getStream(), Object(objNull), true,
   197	                            offsets[i+1] - offsets[i]);
   198	    }
   199	    parser = new Parser(xref, new Lexer(xref, str), false);
   200	    objs[i] = parser->getObj();
   201	    while (str->getChar() != EOF) ;
   202	    delete parser;
   203	  }
   204	
   205	  gfree(offsets);
   206	  ok = true;
   207	}
