   214	Object ObjectStream::getObject(int objIdx, int objNum) {
   215	  if (objIdx < 0 || objIdx >= nObjects || objNum != objNums[objIdx]) {
   216	    return Object(objNull);
   217	  }
   218	  return objs[objIdx].copy();
   219	}
