   489	    more = readXRefStream(obj.getStream(), pos);
   490	
   491	  } else {
   492	    goto err1;
   493	  }
   494	
   495	  delete parser;
   496	  return more;
   497	
   498	 err1:
   499	  delete parser;
   500	  ok = false;
   501	  return false;
   502	}
